import 'package:path/path.dart' as p;
import 'package:sqflite/sqflite.dart';
class LocalDatabase{LocalDatabase._();static final instance=LocalDatabase._();Database? _db;Future<Database> get database async{if(_db!=null)return _db!;final path=p.join(await getDatabasesPath(),'umurava_local.db');_db=await openDatabase(path,version:1,onCreate:(db,version)async{await db.execute('CREATE TABLE local_resources(id TEXT PRIMARY KEY,community_id TEXT NOT NULL,name TEXT NOT NULL,category TEXT NOT NULL,quantity REAL NOT NULL DEFAULT 0,unit TEXT NOT NULL,updated_at TEXT NOT NULL,sync_status TEXT NOT NULL DEFAULT \'LOCAL_ONLY\')');await db.execute('CREATE TABLE outbox(event_id TEXT PRIMARY KEY,entity_type TEXT NOT NULL,entity_id TEXT NOT NULL,operation TEXT NOT NULL,payload TEXT NOT NULL,created_at TEXT NOT NULL,attempts INTEGER NOT NULL DEFAULT 0,status TEXT NOT NULL DEFAULT \'PENDING\')');});return _db!;}Future<List<Map<String,Object?>>> resources()async=>(await database).query('local_resources',orderBy:'name COLLATE NOCASE');}
